import type { NextRequest } from "next/server";

let warnedMissingCronSecret = false;

/**
 * אימות קריאות קרון מ־Vercel: חייב משתנה סביבה `CRON_SECRET` (אותו ערך ב־Authorization: Bearer …).
 * בלי משתנה — כל קריאה נדחית (401), כולל קרונים של Vercel.
 */
export function verifyCronSecret(req: NextRequest): boolean {
  const secret = process.env.CRON_SECRET?.trim();
  if (!secret) {
    if (!warnedMissingCronSecret) {
      warnedMissingCronSecret = true;
      console.error(
        "[cron] CRON_SECRET is not set. Cron routes return 401 until CRON_SECRET is added to the deployment environment (e.g. Vercel → Settings → Environment Variables → Production).",
      );
    }
    return false;
  }
  const auth = req.headers.get("authorization");
  if (auth === `Bearer ${secret}`) return true;
  const q = req.nextUrl.searchParams.get("secret");
  return q === secret;
}

