import { describe, expect, it } from "vitest";
import { computeMenuOpenBroadcastIfDue } from "@/lib/server/menu-open-push";
import { menuOpeningBroadcastCopy } from "@/lib/push-notification-copy";
import { seedSettings } from "@/lib/mock/seed";
import { jerusalemSummerDateTime } from "@/lib/test-datetime";
import type { AdminSettings } from "@/lib/types";

const BASE: AdminSettings = { ...seedSettings };

describe("menuOpeningBroadcastCopy", () => {
  it("sameDay wording → מחר", () => {
    const { body } = menuOpeningBroadcastCopy("21:00", "מחר");
    expect(body).toContain("עד 21:00 מחר");
    expect(body).not.toContain("היום");
  });

  it("eveBefore wording → היום", () => {
    const { body } = menuOpeningBroadcastCopy("21:00", "היום");
    expect(body).toContain("עד 21:00 היום");
  });
});

describe("computeMenuOpenBroadcastIfDue", () => {
  /** רביעי 15.4.2026 — מחר חמישי; יום איסוף פתוח */
  it("weekday eveBefore+sameDay: אחרי שעת פתיחה → due + סגירה במחר", () => {
    const now = jerusalemSummerDateTime("2026-04-15", "16:00");
    const r = computeMenuOpenBroadcastIfDue(BASE, now);
    expect(r.due).toBe(true);
    if (r.due) {
      expect(r.title).toBe("התפריט נפתח להזמנות למחר");
      expect(r.body).toMatch(/עד \d{2}:\d{2} מחר/);
    }
  });

  it("לפני שעת פתיחה → לא due", () => {
    const now = jerusalemSummerDateTime("2026-04-15", "10:00");
    expect(computeMenuOpenBroadcastIfDue(BASE, now)).toEqual({ due: false });
  });

  it("מחר סגור בלוח → לא due", () => {
    const s: AdminSettings = {
      ...BASE,
      closedDayIsoList: ["2026-04-16"],
    };
    const now = jerusalemSummerDateTime("2026-04-15", "16:00");
    expect(computeMenuOpenBroadcastIfDue(s, now)).toEqual({ due: false });
  });

  it("orderOpenTime לא eveBefore → לא due", () => {
    const s: AdminSettings = {
      ...BASE,
      orderTimeScopes: {
        ...BASE.orderTimeScopes,
        orderOpenTime: "sameDay",
      },
    };
    const now = jerusalemSummerDateTime("2026-04-15", "16:00");
    expect(computeMenuOpenBroadcastIfDue(s, now)).toEqual({ due: false });
  });

  /** חמישי 16.4.2026 — מחר שישי; לוח שישי עם סגירה «יום לפני» */
  it("שישי eveBefore+eveBefore: סגירה בניסוח היום", () => {
    const now = jerusalemSummerDateTime("2026-04-16", "16:00");
    const r = computeMenuOpenBroadcastIfDue(BASE, now);
    expect(r.due).toBe(true);
    if (r.due) {
      expect(r.body).toMatch(/עד \d{2}:\d{2} היום/);
    }
  });

  it("menuBroadcastTomorrowAutoAtHHmm דורס את שעת הסף לשידור", () => {
    const s: AdminSettings = {
      ...BASE,
      menuBroadcastTomorrowAutoAtHHmm: "18:00",
    };
    const before = jerusalemSummerDateTime("2026-04-15", "17:00");
    expect(computeMenuOpenBroadcastIfDue(s, before)).toEqual({ due: false });
    const after = jerusalemSummerDateTime("2026-04-15", "18:30");
    expect(computeMenuOpenBroadcastIfDue(s, after).due).toBe(true);
  });
});
